37	// TokenValidatedMsg reports the outcome of authenticating the forge token the
38	// user typed. A nil Err means the token itself is valid; SaveWarning is set
39	// whenever it did not actually end up somewhere durable — either because
40	// Authenticate's own write failed, or because Select had already resolved to
41	// memory-only storage. A token that "validates" but is never asked about
42	// again — this used to be silent, which is exactly what sent a user back to
43	// a logged-out app after being told setup succeeded.
44	type TokenValidatedMsg struct {
45		Err         error
46		SaveWarning string
47	}
