49	func validateTokenCmd(contextName, secretBackend, forgeType, url, token string) tea.Cmd {
50		return func() tea.Msg {
51			sel := credentials.Select(contextName, secretBackend)
52			result, err := session.NewAuth(sel.Storage).Authenticate(context.Background(), forgeType, url, token)
53			if err != nil {
54				return TokenValidatedMsg{Err: err}
55			}
56			warning := result.SaveWarning
57			if warning == "" && !sel.Persists() {
58				warning = sel.Detail
59			}
60			return TokenValidatedMsg{SaveWarning: warning}
61		}
62	}
