91	func checkContainerEngineCmd(preference string) tea.Cmd {
92		return func() tea.Msg {
93			shape, err := engine.Resolve(preference)
94			if err != nil {
95				return ContainerEngineCheckedMsg{Missing: true}
96			}
97			// Safe to mutate: this is a separate, short-lived process from the
98			// real `dk`, which re-resolves its own engine.Current() fresh at
99			// startup (app.resolveContainerEngine) — nothing here leaks into it.
100			engine.SetCurrent(shape)
101			if _, err := docker.FetchCapacity(); err != nil {
102				return ContainerEngineCheckedMsg{Err: err, Name: shape.Name}
103			}
104			return ContainerEngineCheckedMsg{Name: shape.Name}
105		}
106	}
