119	// knownRemoteThemes are the JSON files bundled at the repository root
120	// (themes/*.json) — not installed anywhere by default; README.md documents
121	// copying one into ~/.devdesk/themes/ by hand. This is the fixed list the
122	// wizard offers to fetch automatically instead.
123	var knownRemoteThemes = []string{
124		"catppuccin-mocha", "catppuccin-latte", "catppuccin-frappe", "catppuccin-macchiato",
125		"tokyo-night", "one-dark", "dark-plus", "nord",
126		"solarized-dark", "solarized-light", "github-dark", "github-light",
127	}
128	
129	// remoteThemeBaseURL is a var, not a const, so a test can point it at an
130	// httptest.Server instead of the real repository.
131	var remoteThemeBaseURL = "https://raw.githubusercontent.com/anthnel/devdesk/main/themes/"
132	
133	// remoteThemeFetchTimeout bounds each request. There is no separate
134	// connectivity check (Rule 110 doesn't forbid it, but there is nothing a
135	// preliminary probe would tell us that attempting the real fetch does not) —
136	// an unreachable host fails this fast regardless.
137	var remoteThemeFetchTimeout = 3 * time.Second
138	
139	// RemoteThemesFetchedMsg reports the outcome of the one-shot, best-effort
140	// theme download. Unreachable is set only when the network attempt itself
141	// failed — never for an individual file's own error, which is not this
142	// project's fault to explain to the user.
143	type RemoteThemesFetchedMsg struct {
144		Added       []string
145		Unreachable bool
146	}
147	
148	func fetchRemoteThemesCmd() tea.Cmd {
149		return func() tea.Msg {
150			existing, _ := theme.ListThemes()
151			have := make(map[string]bool, len(existing))
152			for _, name := range existing {
153				have[name] = true
154			}
155	
156			dir, err := theme.ThemeDir()
157			if err != nil {
158				return RemoteThemesFetchedMsg{Unreachable: true}
159			}
160	
161			client := &http.Client{Timeout: remoteThemeFetchTimeout}
162			var added []string
163			for _, name := range knownRemoteThemes {
164				if have[name] {
165					continue
166				}
167				data, err := fetchRemoteTheme(client, name)
168				if err != nil {
169					if len(added) == 0 {
170						// Nothing has succeeded yet, so this reads as "no
171						// network" rather than "this one file is missing" — a
172						// 404 on the project's own bundled theme would be a
173						// repository mistake, not something worth retrying 11
174						// more times for.
175						return RemoteThemesFetchedMsg{Unreachable: true}
176					}
177					continue
178				}
179				if err := os.MkdirAll(dir, 0755); err != nil {
180					continue
181				}
182				if err := os.WriteFile(filepath.Join(dir, name+".json"), data, 0644); err != nil {
183					continue
184				}
185				added = append(added, name)
186			}
187			return RemoteThemesFetchedMsg{Added: added}
188		}
189	}
