191	// fetchRemoteTheme downloads one theme file and sanity-checks that it
192	// actually parses as a theme.Theme before it is ever written to disk.
193	func fetchRemoteTheme(client *http.Client, name string) ([]byte, error) {
194		resp, err := client.Get(remoteThemeBaseURL + name + ".json")
195		if err != nil {
196			return nil, err
197		}
198		defer func() { _ = resp.Body.Close() }()
199		if resp.StatusCode != http.StatusOK {
200			return nil, &themeFetchStatusError{name: name, status: resp.StatusCode}
201		}
202		data, err := io.ReadAll(resp.Body)
203		if err != nil {
204			return nil, err
205		}
206		var t theme.Theme
207		if err := json.Unmarshal(data, &t); err != nil {
208			return nil, err
209		}
210		return data, nil
211	}
